        {
          "h": "How to Brief Your Recommenders (and Why It Matters)",
          "body": "Your SOP tells universities who you THINK you are. Your LOR shows who others THINK you are. They should align.\n\nWhen asking a professor or manager for a letter of recommendation, share your SOP (or a 1-page summary of your goals). Tell them:\n• 'I want to study X at the graduate level.'\n• 'The program emphasizes Y (systems design, climate science, etc.). Can you speak to examples where I showed strength in Y?'\n• 'I'm applying to 5 universities. Here's what they're looking for.'\n\nA recommender who reads your SOP writes a stronger letter because they can target it to what the program cares about. A letter that says 'She's brilliant at algorithms' is generic. A letter that says 'She optimized Flipkart's recommendation latency AND thought deeply about fairness trade-offs — exactly what your distributed systems program needs' is gold.\n\nRead more: [How to Write a Strong Letter of Recommendation](/blog/how-to-write-strong-lor/)"
        }
