          "body": "Even expensive countries offer scholarships to reduce your out-of-pocket cost.\n\n**USA**:\n- **Fulbright (USA)**: Up to $20,000/year for Indian graduates. Apply via US Embassy in India. Highly competitive.\n- **University-specific**: Check individual school financial aid. MIT, Stanford, Yale offer need-based aid to international students (rare). Top schools: 50% of international applicants are full-funded or heavily subsidized.\n- **Private scholarships**: Inlaks, Rotary Foundation (up to $10,000), AFS (American Field Service).\n\n**Canada**:\n- **Government scholarships**: Vanier Canada Graduate Scholarships (CAD $50,000/year) for top students. Apply via individual universities.\n- **University-specific**: University of Toronto, UBC, McGill offer entrance scholarships (CAD $5,000–15,000). Check university websites.\n- **Private**: Inlaks, Rotary, AFS scholarships work in Canada too.\n\n**UK**:\n- **Chevening**: Up to £20,000 (tuition) for Master's degrees. Highly competitive. Apply via Chevening website.\n- **Commonwealth Scholarships**: Limited to few countries (India has ~50 slots/year). Full tuition + stipend. Apply early.\n- **University-specific**: Oxford/Cambridge offer Clarendon, Standard Studentships (covers tuition + living). Highly competitive.\n\n**Australia**:\n- **Australia Awards (Department of Foreign Affairs & Trade)**: Full scholarship (tuition + living) for developing countries. India: ~200 slots/year. Apply via Australian High Commission.\n- **University Scholarships**: Many offer Merit-based (AUD $10,000–30,000/year). Check individual university websites.\n\n**Germany**:\n- **DAAD**: €861–1,260/month for Master's students. Highly competitive. Apply 6 months before intake.\n- **University-specific**: TU Munich, TU Darmstadt, Heidelberg offer small grants. Check International Office of your target university.\n\n**Ireland**:\n- **Limited scholarships**: Ireland government offers few scholarships for international students. However, many universities offer entrance scholarships (€5,000–10,000). Apply directly to universities."
