          "h": "Your 45-Day PTE 79+ Preparation Plan",
          "body": "**Week 1–2: Diagnostic & Fundamentals**\n\n- Take a full diagnostic mock test. Identify weak areas (usually Listening or Speaking & Writing).\n- Spend 1 hour daily on weak areas: If listening is weak, practice \"Summarize Spoken Text\" and \"Write from Dictation\" exclusively.\n- Familiarize yourself with the PTE interface (how to click, type, speak into the microphone).\n\n**Week 3–4: Task Mastery**\n\n- Dedicate each day to one task type:\n  - Day 1: Read-aloud (10 practice texts).\n  - Day 2: Repeat sentence (10 sentences).\n  - Day 3: Describe image (5 images).\n  - Day 4: Retell lecture (5 lectures).\n  - Day 5: Summarize text (5 texts).\n  - Day 6: Fill blanks (10 blanks).\n  - Day 7: Full mock test.\n- Record yourself; listen back and score against the PTE rubric.\n\n**Week 5–6: Integration & Speed**\n\n- Practice full mock tests under timed conditions (3 hours, no breaks).\n- Review your mistakes. Are they due to lack of knowledge, time pressure, or carelessness? Address the root cause.\n- If listening is weak, join an online PTE group or hire a tutor for feedback on your retell-lecture responses.\n\n**Week 7–8: Final Polish & Test Strategy**\n\n- Take 2–3 final mock tests.\n- For each, time yourself precisely and aim to finish each section 5 minutes early.\n- Review your weak tasks one more time.\n- On test day, read the instructions carefully and trust your preparation.",
