          "h": "The Study-to-PR Timeline for Australian International Students",
          "body": "Here's a realistic timeline to reach 65 points and get PR:\n\n**Years 1–2: Study Phase**\nComplete a bachelor's degree in Australia (or master's for faster PR pathway). During your final semester, apply for post-study work visa (subclass 485).\n\n**Year 2–3: Work Phase**\nAfter graduation, you receive a post-study work visa:\n- Bachelor's degree: 1.5–2 years work visa\n- Master's degree: 2–3 years work visa\n- PhD: 3 years work visa\n\nWork in your skilled occupation for 1+ years. After 12 months, you're eligible to apply for PR.\n\n**Timeline at 1-year mark (after graduation):**\n- Age points: 30 (if 25–32 years old)\n- English points: 10–20 (depending on test)\n- Education: 15\n- Work experience: 5 (after 1 year)\n- **Total: 60–70 points**\n\nIf you're at 65+, apply immediately. If you're at 60–64, get state nomination (190, +5 pts = 65+) or apply for regional visa (491, +10 pts = 70+).\n\n**Total timeline:** 2 years study + 1 year work + 3–12 months PR processing = 3–4 years from enrollment to permanent residency.",
