      "id": "toefl-writing-integrated-task-template",
      "tag": "TOEFL",
      "date": "2026",
      "title": "TOEFL Writing Integrated Task 2026: Template, Structure & Band 24+ Tips",
      "excerpt": "A copy-ready TOEFL Integrated Writing template that works for any passage-lecture pair — plus the exact structure, key phrases, and the most common mistakes that drop your score below 20.",
      "kw": "toefl writing integrated task, toefl integrated writing template, toefl integrated task tips, toefl writing task 1 structure, toefl integrated writing score 24",
      "sections": [
        {
          "h": "What the Integrated Task tests",
          "body": "You read a passage (3 minutes, stays visible), then listen to a lecture that challenges or qualifies the passage's claims. You write a 150–225 word response summarising how the lecture relates to the reading. You are NOT being asked your opinion — only to accurately describe the lecture's points and how they respond to the reading. Scored 0–5 (reported as 0–30 scale). You have 20 minutes."
        },
        {
          "h": "The template that works",
          "body": "Para 1 (Introduction, 2 sentences): 'The reading argues that [main claim of passage]. However, the lecturer challenges/qualifies/casts doubt on this by arguing that [overall lecture position].' Para 2 (Point 1, 3–4 sentences): 'First, the reading claims [point 1]. The lecturer counters this by stating [lecture response 1], explaining that [specific detail from lecture].' Para 3 (Point 2): Same structure. Para 4 (Point 3): Same structure. No conclusion paragraph needed — the task does not require one."
        },
        {
          "h": "Key phrases for linking",
          "body": "Reading → lecture contrast: 'While the passage contends...the professor argues...', 'The lecturer challenges the reading's claim that...', 'In contrast to the reading, the professor states...'. Adding lecture detail: 'Specifically, the lecturer points out that...', 'According to the professor,...', 'The lecture illustrates this by noting that...'. Never say 'In my opinion' or 'I believe' — this is not a discursive essay."
        },
        {
          "h": "What kills your score below 20",
          "body": "Copying sentences from the reading verbatim (paraphrase all reading content). Summarising the reading instead of showing how the lecture responds to it. Missing one of the three lecture points entirely. Writing fewer than 150 words. Mixing up which side said what (keep reading vs lecture clearly separated)."
        },
        {
          "h": "Note-taking strategy during the lecture",
          "body": "The lecture audio plays once — you cannot replay it. Take linear notes organised by lecture point number (1, 2, 3). Write the key noun/verb of each claim, not complete sentences. The reading remains on screen so you do not need to note it — focus 100% of your note energy on the lecture."
        },
        {
          "h": "Practise the full task free",
          "body": "The integrated task is the most teachable part of TOEFL Writing — with the right template, most candidates add 4–6 score points in 2 weeks of targeted practice. Take free TOEFL Writing mocks on LandingPrep, use this template, and compare your response to the model answer after each attempt."
        }
      ]
