      "excerpt": "Master the GRE Analyze an Argument task with a reusable 5-paragraph template, logical fallacy detection, and real-scored sample essays. Learn how to score 4.5+ and impress admissions committees.",
      "kw": "GRE analytical writing template, analyze an argument essay, GRE AWA scoring, GRE argument essay, logical fallacies GRE",
      "sections": [
        {
          "h": "What is the GRE Analyze an Argument (AAA) Task?",
          "body": "You receive a short argument (4–7 sentences) and have 30 minutes to analyze its logical validity. The argument makes a claim, provides some evidence, and reaches a conclusion. Your job is NOT to agree or disagree, but to critique its reasoning. You identify unsupported assumptions, logical gaps, evidence weaknesses, and alternative explanations. Essays are scored 0–6; a 4.0 is 40th percentile, a 5.0 is 80th percentile, and a 6.0 is 99th percentile for graduate admissions."
        },
        {
          "h": "GRE AWA Scoring Rubric: What Readers Look For",
          "body": "Readers assess whether you identify major logical flaws (not minor grammatical issues). You must articulate why these flaws matter (an assumption is unjustified, a premise is false, or evidence does NOT support the conclusion). Your essay structure and clarity matter; a poorly organized 5-paragraph essay scores lower than a chaotic 3-paragraph essay. Strong command of English is expected: varied vocabulary, error-free grammar, and logical transitions. You do NOT need to agree with the argument; objectively analyzing its logic is sufficient."
        },
        {
          "h": "The 5-Paragraph Argument Analysis Template",
          "body": "Paragraph 1 (restatement + preview): Restate the argument and preview the 2–3 major flaws. Keep it brief (3–4 sentences). Paragraphs 2–4 (flaw analysis, one per paragraph): For each flaw, explain what the argument assumes, why that assumption is questionable, and what evidence would strengthen the argument. Use transitions: 'First,' 'Second,' 'Third,' 'Furthermore.' Paragraph 5 (conclusion): Summarize the argument's weaknesses and note that it might be valid if certain assumptions were supported. Avoid saying 'the argument is completely wrong' — qualified analysis scores higher."
        },
        {
          "h": "Sample Argument Analysis Structure (Customize Your Flaws)",
          "body": "Argument: 'Company X's productivity increased 20% after implementing a 4-day work week. Therefore, all companies should adopt a 4-day work week to boost productivity.' Flaw 1: Unwarranted generalization. The argument assumes that what works for Company X applies to ALL companies. But Company X may be small, tech-focused, or already highly motivated. Different industries (manufacturing, retail, healthcare) may not benefit equally. Flaw 2: Causation vs. correlation. The argument assumes the 4-day week CAUSED the 20% increase. But other factors changed simultaneously: new equipment, better training, seasonal demand, or economic conditions. Without controlling for these variables, we cannot conclude causation. Flaw 3: Incomplete evidence. The argument provides no data on costs, employee satisfaction, or long-term sustainability. A 20% productivity bump might cost 30% more in overtime or burnout."
        },
        {
          "h": "10 Logical Fallacies to Identify in GRE Arguments",
          "body": "Hasty generalization (one example → universal rule). Causal fallacy (A happened before B → A caused B). False dilemma (only two options when more exist). Appeal to authority (expert said it → must be true). Circular reasoning (conclusion is the premise). Equivocation (a word means two different things). False analogy (two situations are not comparable). Straw man (attacking a distorted version of the argument). Ad hominem (attacking the speaker, not the argument). Begging the question (assuming what you're trying to prove)."
        },
        {
          "h": "Scoring 4.5+: Depth and Nuance in Argument Analysis",
          "body": "To score 4.5+, go beyond identifying flaws; explain their significance. Rather than 'The argument assumes Company X's success applies to all companies,' write: 'The argument commits a hasty generalization by assuming Company X's context — likely a small, tech-savvy firm with high baseline motivation — is representative of all industries. Retail and manufacturing operate under different constraints and labor dynamics, making the policy transfer questionable.' Use specific terms: 'assumes,' 'presupposes,' 'fails to consider,' 'overlooks.' Anticipate counter-arguments: 'While one might argue that productivity gains are universal, evidence from competing sectors suggests otherwise.' Distinguish between invalid reasoning and incomplete evidence; an argument can be logically sound but insufficiently proven."
        },
        {
          "h": "Common AWA Mistakes That Cap Your Score at 3.5",
          "body": "Agreeing or disagreeing with the argument instead of analyzing its logic ('I disagree because productivity is not the only measure of success'). Attacking the subject matter rather than the reasoning ('A 4-day work week is bad for the economy'). Writing a generic essay that could fit any argument. Not explicitly linking assumptions to the conclusion. Ignoring counterarguments or alternative explanations. Using overly simple vocabulary or sentence structures. Spending 20+ minutes on one flaw and rushing the rest."
        },
        {
          "h": "Practice Argument Essays with Timed Feedback",
          "body": "Strengthen your analytical writing on LandingPrep's free GRE writing simulator. Practice 10–15 timed argument essays, receive AI-powered feedback on flaw identification and reasoning clarity, and refine your template. Most students improve from 3.5 to 4.5+ in 3–4 weeks of consistent practice. Your AWA score does not affect your math or verbal percentiles, but a 4.0+ helps your graduate school application stand out."
        }
      ]
