      "id": "toefl-speaking-templates-2026",
      "tag": "TOEFL",
      "date": "2026",
      "title": "TOEFL Speaking Templates: Independent & Integrated Tasks (2026)",
      "excerpt": "Master TOEFL Speaking with reusable templates for Independent and Integrated tasks. Learn scoring criteria, delivery tips, and practice strategies to score 26–30 in the revised TOEFL.",
      "kw": "TOEFL speaking template, TOEFL speaking task, TOEFL speaking tips, band 8 TOEFL speaking, TOEFL speaking practice",
      "sections": [
        {
          "h": "TOEFL Speaking Overview: 4 Tasks, 17 Minutes, Scored 0–30",
          "body": "The TOEFL Speaking section has 4 tasks. Task 1 (Independent): You speak for 45 seconds on a personal opinion topic. Task 2 (Integrated – Read/Listen/Speak): You read a short announcement, listen to a conversation, and summarize them in 60 seconds. Task 3 (Integrated – Read/Listen/Speak): You read an academic passage, listen to a lecture, and explain the connection in 60 seconds. Task 4 (Integrated – Listen/Speak): You listen to a lecture and summarize it in 60 seconds. Scoring is 0–30; 26+ is excellent and competitive for US universities. Raters assess fluency (smooth, natural speech with minimal hesitation), coherence (ideas are organized and easy to follow), vocabulary range, and pronunciation."
        },
        {
          "h": "Task 1 (Independent) Template: 45-Second Personal Opinion",
          "body": "Setup (10 sec): State your opinion clearly. Use a strong opening: 'I strongly believe that…' or 'In my view, the best… is…' Reasoning (20 sec): Give 2 reasons with brief examples. Use transitions: 'First,' 'Second,' 'Another reason is.' Conclusion (5 sec): Restate your position. Example template: 'I strongly prefer studying in groups because it enhances understanding and builds collaboration skills. First, explaining concepts to peers forces me to think critically. Second, I learn different problem-solving approaches from groupmates. Therefore, I believe group study is more effective than solo study.' Practice your response at a natural pace until it sounds conversational, not scripted."
        },
        {
          "h": "Task 2 (Integrated) Template: Read + Listen + Summarize (60 sec)",
          "body": "You read a short notice (e.g., dorm change, class cancellation), listen to 2 students discuss it, and summarize. Structure (15 sec intro): 'The announcement states that [main point]. [Student name 1] says [his/her perspective]. [Student name 2] says [his/her perspective].' Opinion (30 sec middle): Explain the two perspectives. Example: 'Student 1 thinks the policy is positive because [reason]. However, Student 2 disagrees because [reason].' Conclusion (5 sec): Wrap up. 'Overall, [Student name] seems more concerned about [impact].' Practice distinguishing opinions; note that neither student is wrong — they simply see different impacts."
        },
        {
          "h": "Task 3 (Integrated) Template: Read + Listen + Connect (60 sec)",
          "body": "You read an academic concept (e.g., cognitive bias), listen to a lecture example, and explain the connection. Setup (15 sec): 'The reading discusses [concept]. The lecture illustrates this with [example].' Connection (35 sec): 'Specifically, the [part of example] demonstrates [part of concept] because [explanation].' Conclusion (5 sec): 'This shows how the concept applies to real-world situations.' Example: 'The reading defines confirmation bias — the tendency to search for evidence supporting your belief. The lecture describes a manager who only asks positive employees for feedback, ignoring negative opinions. This exemplifies confirmation bias because the manager selects information that confirms his belief that the company is doing well, dismissing contrary evidence.'"
        },
        {
          "h": "Task 4 (Integrated) Template: Listen + Summarize (60 sec)",
          "body": "You listen to an academic lecture and summarize the main idea and examples. Setup (10 sec): 'The lecture is about [main topic].' Main idea (20 sec): 'The professor explains that [core concept and why it matters].' Examples (25 sec): 'The lecture provides two examples: [Example 1] and [Example 2], both illustrating [how they relate to the main idea].' Example: 'The lecture is about photosynthesis. The professor explains that plants convert light energy into chemical energy through photosynthesis, which is essential for life on Earth. Two examples given are C3 photosynthesis, efficient in cool climates, and C4 photosynthesis, efficient in hot climates, showing how photosynthesis adapts to different environments.'"
        },
        {
          "h": "Pronunciation and Delivery Tips for High Scores",
          "body": "Speak at a natural, steady pace — neither rushed (1.5x speed) nor slow (0.5x speed). Standard pace is 120–150 words per minute. Stress key words: 'The PROFessor EXplains that phoTOsynthesis is ESSENTIAL.' Use intonation to show relationships: rise at the end of a list, fall at the end of a statement. Pause briefly between ideas (1–2 seconds) but not within clauses. Articulate clearly: 'th' in 'think' (not 'sink'), 'r' in 'reading' (not 'leading'). Avoid filler sounds ('uh,' 'um,' 'like') or self-corrections unless necessary."
        },
        {
          "h": "Common TOEFL Speaking Mistakes That Lower Your Score",
          "body": "Speaking too fast or mumbling, making words unclear. Very long pauses (3+ seconds of silence hurts coherence). Memorized, robotic-sounding responses that lack natural intonation. Over-explaining or going significantly over the time limit. Not addressing the prompt directly (e.g., summarizing only Task 3's lecture, missing the reading connection). Using overly simple vocabulary when you have better options. Grammatical errors that interfere with meaning (e.g., verb tenses so confused the idea is unclear)."
        },
        {
          "h": "Track Your Progress with Free TOEFL Speaking Practice",
          "body": "Use LandingPrep's free TOEFL speaking simulator to practice all 4 tasks with timed responses and AI-powered feedback on fluency, coherence, and accuracy. Record your responses and listen back to identify speech clarity and pacing issues. Aim for 15–20 practice rounds before your exam; most students improve 2–4 points in speaking score with consistent practice."
        }
      ]
