            "**Good: Thesis/project advisor** – If you completed a thesis, capstone, or major research project, your advisor is an excellent choice. They can attest to your research capability, independence, and problem-solving—especially valuable for research-heavy programs.",
            "**Good: Work supervisor** – If you've worked professionally for 1+ year, a direct manager is a strong recommender. They speak to your technical skills, collaboration, work ethic, and professional maturity. Ideal for students with 2–5 years of work experience.",
