            "**Weak: Same-level colleague or junior staff** – Peers or people you managed carry less weight than direct supervisors. Use only if you have no alternative.",
            "**Never: Relatives or family friends** – Admissions committees immediately discount letters from family, even if they're successful professionals. Only if the relative is a senior faculty member or CEO at a well-known company AND has directly supervised your work should you consider it (rare)."
