          "h": "Academic LOR Sample (from a Professor)",
          "body": "---\n\nDear Admissions Committee,\n\nI am writing to strongly recommend Asha Sharma for admission to your Master's in Computer Science program. I have known Asha for two years as the instructor of her Data Structures and Algorithms (DSA) course and her capstone project advisor for a machine learning research project on anomaly detection in medical imaging.\n\nAsha is an exceptional student who combines strong theoretical knowledge with practical problem-solving skills. In my DSA course, she consistently earned the highest marks (98/100), and more impressively, she demonstrated a deep understanding of algorithmic complexity—not just memorizing solutions, but independently optimizing her code to achieve O(n log n) performance where her peers stopped at O(n²). During the final exam, she was the only student to correctly solve all five bonus algorithmic problems, showcasing both depth and speed of thinking.\n\nHer capstone project exemplifies her research potential. Working on automated detection of tumors in CT scans using convolutional neural networks, Asha single-handedly improved the model's accuracy from 87% to 94% by implementing attention mechanisms and rebalancing the training dataset. She authored the corresponding research paper, which I believe is publishable in a peer-reviewed venue. More importantly, she approached roadblocks systematically—when initial models plateaued, she read relevant literature, consulted published papers, and experimented iteratively. This independent research mindset is rare in undergraduates and a strong predictor of success in a research-focused master's program.\n\nBeyond academics, Asha is a thoughtful colleague and mentor. She has informally tutored three struggling classmates in DSA, patiently explaining linked list operations and dynamic programming until concepts 'clicked'—a mark of someone who deeply understands the material and cares about others' growth.\n\nRegarding fit for your program: Your MS in Computer Science emphasizes artificial intelligence, systems design, and distributed computing. Asha's capstone work in deep learning, combined with her stated interest in building scalable ML platforms, aligns perfectly. I have no doubt she will thrive in your curriculum and contribute meaningfully to your research community.\n\nIn my 18 years of teaching, Asha ranks among the top 5% of students I have encountered. I recommend her without reservation.\n\nSincerely,\nDr. Rajesh Kumar\nAssociate Professor of Computer Science\nIndian Institute of Technology, Delhi\nrajesh.kumar@iitd.ac.in\n+91-11-XXXX-XXXX\n\n---",
